QString normalized_plan_name(QString value) {
    value = value.trimmed();
    value.replace(QLatin1Char('_'), QLatin1Char(' '));
    value.replace(QLatin1Char('-'), QLatin1Char(' '));
    const auto words = value.toLower().split(QLatin1Char(' '), Qt::SkipEmptyParts);
    QStringList titled;
    titled.reserve(words.size());
    for (auto word : words) {
        if (!word.isEmpty()) word[0] = word[0].toUpper();
        titled.push_back(std::move(word));
    }
    return titled.join(QLatin1Char(' '));
}

bool plan_name_contains(const QString& value, std::initializer_list<const char*> terms) {
    const auto normalized = value.trimmed().toLower();
    return std::any_of(terms.begin(), terms.end(), [&](const char* term) {
        return normalized.contains(QString::fromLatin1(term));
    });
}

PlanAreaPresentation plan_area_presentation(QString classification) {
    classification = classification.trimmed().toLower();
    if (plan_name_contains(classification, {"garage", "carport", "parking", "loading"})) {
        return {QColor(194, 116, 24), QColor(242, 184, 102), QColor(237, 197, 132),
                QStringLiteral("forward_diagonal"), true};
    }
    if (plan_name_contains(classification, {"porch", "patio", "deck", "balcony", "terrace"})) {
        return {QColor(66, 135, 92), QColor(143, 213, 169), QColor(178, 218, 189),
                QStringLiteral("solid"), true};
    }
    if (plan_name_contains(classification, {"excluded", "deduction", "void", "open to below"})) {
        return {QColor(137, 86, 86), QColor(224, 160, 160), QColor(221, 190, 190),
                QStringLiteral("diagonal"), true};
    }
    if (plan_name_contains(classification, {"storage", "utility", "mechanical", "warehouse"})) {
        return {QColor(92, 106, 121), QColor(186, 199, 214), QColor(197, 206, 216),
                QStringLiteral("solid"), true};
    }
    if (plan_name_contains(classification,
                           {"living", "gross", "building area", "residential"})) {
        return {QColor(37, 91, 145), QColor(128, 194, 246), QColor(178, 210, 235),
                QStringLiteral("solid"), true};
    }
    return {};
}

QString plan_area_label(const Entity& entity) {
    auto value = read_string(entity.properties, "name")
        .value_or(read_string(entity.properties, "classification").value_or(""));
    const auto normalized = QString::fromStdString(value).trimmed().toLower();
    if (normalized.isEmpty()) return {};
    static const std::set<QString> generic{
        QStringLiteral("measurement"), QStringLiteral("boundary"),
        QStringLiteral("interior"), QStringLiteral("exterior"),
        QStringLiteral("living"), QStringLiteral("living area"),
        QStringLiteral("living_area"), QStringLiteral("gross building area"),
        QStringLiteral("gross_building_area"), QStringLiteral("unassigned")};
    if (entity.type == "measurement_boundary" && generic.contains(normalized)) return {};
    if (entity.type == "room_boundary" && normalized == QStringLiteral("room")) {
        return QStringLiteral("Room");
    }
    return normalized_plan_name(QString::fromStdString(value));
}

Vec2 plan_label_anchor(const Boundary& boundary) {
    bool line_only = !boundary.empty();
    double twice_area = 0.0;
    double x_sum = 0.0;
    double y_sum = 0.0;
    for (const auto& segment : boundary) {
        if (segment.sweep_radians != 0.0) line_only = false;
        const auto cross = segment.start.x * segment.end.y -
                           segment.end.x * segment.start.y;
        twice_area += cross;
        x_sum += (segment.start.x + segment.end.x) * cross;
        y_sum += (segment.start.y + segment.end.y) * cross;
    }
    if (line_only && std::abs(twice_area) > default_geometry_tolerance_metres &&
        std::isfinite(x_sum) && std::isfinite(y_sum)) {
        return {x_sum / (3.0 * twice_area), y_sum / (3.0 * twice_area)};
    }
    const auto bounds = boundary_bounds(boundary);
    return {std::midpoint(bounds.minimum.x, bounds.maximum.x),
            std::midpoint(bounds.minimum.y, bounds.maximum.y)};
}

Boundary window_plan_symbol(const Segment& baseline, double offset, double width,
                            double wall_thickness) {
    const auto dx = baseline.end.x - baseline.start.x;
    const auto dy = baseline.end.y - baseline.start.y;
    const auto length = std::hypot(dx, dy);
    if (!(length > default_geometry_tolerance_metres) || !(width > 0.0) ||
        !std::isfinite(length) || !std::isfinite(offset) || !std::isfinite(width)) {
        return {};
    }
    const Vec2 tangent{dx / length, dy / length};
    const Vec2 normal{-tangent.y, tangent.x};
    const auto inset = std::clamp(std::abs(wall_thickness) * 0.22, 0.015, 0.06);
    const Vec2 start{baseline.start.x + tangent.x * offset,
                     baseline.start.y + tangent.y * offset};
    const Vec2 end{start.x + tangent.x * width, start.y + tangent.y * width};
    return {
        {{start.x + normal.x * inset, start.y + normal.y * inset},
         {end.x + normal.x * inset, end.y + normal.y * inset}, 0.0},
        {{start.x - normal.x * inset, start.y - normal.y * inset},
         {end.x - normal.x * inset, end.y - normal.y * inset}, 0.0},
        {{start.x - normal.x * inset, start.y - normal.y * inset},
         {start.x + normal.x * inset, start.y + normal.y * inset}, 0.0},
        {{end.x - normal.x * inset, end.y - normal.y * inset},
         {end.x + normal.x * inset, end.y + normal.y * inset}, 0.0},
    };
}

json parse_bounded_string_attributes(const QString& encoded_value) {
    auto encoded = encoded_value.trimmed().toStdString();
    if (encoded.empty()) encoded = "{}";
    const auto attributes = json::parse(encoded);
    if (!attributes.is_object() || attributes.size() > 256) {
        throw std::invalid_argument(
            "Attributes must be a JSON object with at most 256 entries.");
    }
    for (const auto& [key, value] : attributes.items()) {
        if (key.empty() || key.size() > 256 || !value.is_string() ||
            value.get_ref<const std::string&>().size() > 16384 ||
            value.get_ref<const std::string&>().find('\0') != std::string::npos) {
            throw std::invalid_argument(
                "Attributes must contain short string key/value pairs.");
        }
    }
    return attributes;
}

std::optional<double> read_finite_number(const json& object, std::string_view key) {
    const auto key_string = std::string(key);
    if (!object.contains(key_string) || !object.at(key_string).is_number()) {
        return std::nullopt;
    }
    const auto value = object.at(key_string).get<double>();
    return std::isfinite(value) ? std::optional<double>(value) : std::nullopt;
}

SlabElementKind read_slab_element_kind(const json& properties) {
    if (!properties.contains("element_kind")) return SlabElementKind::slab;
    const auto& value = properties.at("element_kind");
    if (!value.is_string()) {
        throw std::invalid_argument(
            "element_kind must be one of slab, floor, ceiling, or foundation");
    }
    const auto parsed = parse_slab_element_kind(value.get_ref<const std::string&>());
    if (!parsed.has_value()) {
        throw std::invalid_argument(
            "element_kind must be one of slab, floor, ceiling, or foundation");
    }
    return *parsed;
}

std::optional<HostedOpening> read_hosted_opening(const Entity& entity,
                                                 QString* error = nullptr) {
    const auto wall_id = read_string(entity.properties, "wall_id");
    const auto offset = read_finite_number(entity.properties, "offset_m");
    const auto width = read_finite_number(entity.properties, "width_m");
    const auto sill = read_finite_number(entity.properties, "sill_m");
    const auto height = read_finite_number(entity.properties, "height_m");
    if (!wall_id.has_value() || !offset.has_value() || !width.has_value() ||
        !sill.has_value() || !height.has_value()) {
        if (error != nullptr) {
            *error = QStringLiteral("Opening requires wall_id, offset_m, width_m, sill_m, and height_m.");
        }
        return std::nullopt;
    }
    if (wall_id->empty()) {
        if (error != nullptr) {
            *error = QStringLiteral("Opening wall_id cannot be empty.");
        }
        return std::nullopt;
    }
    return HostedOpening{entity.id, *offset, *width, *sill, *height};
}

std::optional<Vec2> point_at_segment(const Segment& segment, double fraction) {
    if (!std::isfinite(fraction)) {
        return std::nullopt;
    }
    fraction = std::clamp(fraction, 0.0, 1.0);
    if (segment.sweep_radians == 0.0) {
        return Vec2{std::lerp(segment.start.x, segment.end.x, fraction),
                    std::lerp(segment.start.y, segment.end.y, fraction)};
    }
    const auto chord_x = segment.end.x - segment.start.x;
    const auto chord_y = segment.end.y - segment.start.y;
    const auto chord_length = std::hypot(chord_x, chord_y);
    const auto tangent = std::tan(segment.sweep_radians * 0.5);
    if (!(chord_length > 1e-7) || !std::isfinite(tangent) || std::abs(tangent) <= 1e-12) {
        return std::nullopt;
    }
    const auto midpoint = Vec2{(segment.start.x + segment.end.x) * 0.5,
                               (segment.start.y + segment.end.y) * 0.5};
    const auto factor = chord_length / (2.0 * tangent);
    const auto center = Vec2{midpoint.x - chord_y / chord_length * factor,
                             midpoint.y + chord_x / chord_length * factor};
    const auto radius = std::hypot(segment.start.x - center.x, segment.start.y - center.y);
    if (!(radius > 1e-7) || !std::isfinite(radius)) {
        return std::nullopt;
    }
    const auto start_angle = std::atan2(segment.start.y - center.y,
                                        segment.start.x - center.x);
    const auto angle = start_angle + segment.sweep_radians * fraction;
    return Vec2{center.x + radius * std::cos(angle), center.y + radius * std::sin(angle)};
}

// Build the retained linework for a segment dimension. The analytical
// dimension value remains the stable BoundaryDimension record; this overlay
// is only presentation geometry and is regenerated from the current source
// segment on every refresh. Curved dimensions use an offset analytical arc
// with radial extension lines, so the displayed linework has the same sweep
// and true arc-length geometry as the source.
std::optional<Boundary> dimension_overlay(const Segment& source, Vec2 text_position) {
    const auto dx = source.end.x - source.start.x;
    const auto dy = source.end.y - source.start.y;
    const auto length = std::hypot(dx, dy);
    if (!(length > 1e-7) || !std::isfinite(length)) return std::nullopt;
    const Vec2 midpoint{(source.start.x + source.end.x) * 0.5,
                        (source.start.y + source.end.y) * 0.5};
    if (source.sweep_radians == 0.0) {
        const Vec2 tangent{dx / length, dy / length};
        const Vec2 normal{-tangent.y, tangent.x};
        const auto offset = (text_position.x - midpoint.x) * normal.x +
                            (text_position.y - midpoint.y) * normal.y;
        if (!std::isfinite(offset)) return std::nullopt;
        const Vec2 center{midpoint.x + normal.x * offset,
                          midpoint.y + normal.y * offset};
        const Vec2 half{tangent.x * length * 0.5, tangent.y * length * 0.5};
        const Vec2 dimension_start{center.x - half.x, center.y - half.y};
        const Vec2 dimension_end{center.x + half.x, center.y + half.y};
        return Boundary{
            Segment{source.start, dimension_start, 0.0},
            Segment{source.end, dimension_end, 0.0},
            Segment{dimension_start, dimension_end, 0.0},
        };
    }

    const auto half_sweep = source.sweep_radians * 0.5;
    const auto tangent = std::tan(half_sweep);
    const auto sine = std::sin(std::abs(half_sweep));
    if (!std::isfinite(tangent) || tangent == 0.0 || !std::isfinite(sine) || sine == 0.0) {
        return std::nullopt;
    }
    const Vec2 center{midpoint.x - dy / length * (length / (2.0 * tangent)),
                      midpoint.y + dx / length * (length / (2.0 * tangent))};
    const auto source_radius = std::hypot(source.start.x - center.x,
                                          source.start.y - center.y);
    const auto requested_radius = std::hypot(text_position.x - center.x,
                                              text_position.y - center.y);
    if (!(source_radius > 1e-7) || !std::isfinite(source_radius) ||
        !std::isfinite(requested_radius)) {
        return std::nullopt;
    }
    const auto dimension_radius = requested_radius > 1e-7
                                      ? requested_radius
                                      : source_radius + std::max(0.25, source_radius * 0.1);
    const auto start_angle = std::atan2(source.start.y - center.y,
                                        source.start.x - center.x);
    const Vec2 dimension_start{center.x + dimension_radius * std::cos(start_angle),
                               center.y + dimension_radius * std::sin(start_angle)};
    const Vec2 dimension_end{center.x + dimension_radius *
                                                std::cos(start_angle + source.sweep_radians),
                             center.y + dimension_radius *
                                                std::sin(start_angle + source.sweep_radians)};
    return Boundary{
        Segment{source.start, dimension_start, 0.0},
        Segment{source.end, dimension_end, 0.0},
        Segment{dimension_start, dimension_end, source.sweep_radians},
    };
}

QString format_dimension_angle(double radians) {
    if (!std::isfinite(radians)) {
        return QStringLiteral("—");
    }
    const auto degrees = radians * 180.0 / std::numbers::pi;
    if (!std::isfinite(degrees)) {
        return QStringLiteral("—");
    }
    return QStringLiteral("%1°").arg(degrees, 0, 'f', 1);
}

QString format_dimension_area(double square_metres, bool metric) {
    if (!std::isfinite(square_metres)) {
        return QStringLiteral("—");
    }
    if (metric) {
        return QStringLiteral("%1 m²").arg(square_metres, 0, 'f', 2);
    }
    constexpr double square_metres_per_square_foot = 0.09290304;
    return QStringLiteral("%1 ft²")
        .arg(square_metres / square_metres_per_square_foot, 0, 'f', 1);
}

std::optional<Vec2> dimension_tangent_at_vertex(const IdentifiedSegment& identified,
                                                std::string_view vertex_id) {
    const auto& segment = identified.segment;
    const bool at_start = identified.start_vertex_id == vertex_id;
    const bool at_end = identified.end_vertex_id == vertex_id;
    if (at_start == at_end) {
        return std::nullopt;
    }
    Vec2 tangent{segment.end.x - segment.start.x, segment.end.y - segment.start.y};
    if (segment.sweep_radians != 0.0) {
        const auto chord = std::hypot(tangent.x, tangent.y);
        const auto half_sweep = segment.sweep_radians * 0.5;
        const auto arc_tangent = std::tan(half_sweep);
        if (!(chord > 1e-7) || !std::isfinite(arc_tangent) || std::abs(arc_tangent) <= 1e-12) {
            return std::nullopt;
        }
        const Vec2 midpoint{(segment.start.x + segment.end.x) * 0.5,
                            (segment.start.y + segment.end.y) * 0.5};
        const auto center_offset = chord / (2.0 * arc_tangent);
        const Vec2 center{midpoint.x - tangent.y / chord * center_offset,
                          midpoint.y + tangent.x / chord * center_offset};
        const Vec2 point = at_start ? segment.start : segment.end;
        const Vec2 radial{point.x - center.x, point.y - center.y};
        tangent = segment.sweep_radians > 0.0
                      ? Vec2{-radial.y, radial.x}
                      : Vec2{radial.y, -radial.x};
        if (at_end) tangent = {-tangent.x, -tangent.y};
    } else if (at_end) {
        tangent = {-tangent.x, -tangent.y};
    }
    const auto magnitude = std::hypot(tangent.x, tangent.y);
    if (!(magnitude > 1e-7) || !std::isfinite(magnitude)) {
        return std::nullopt;
    }
    return Vec2{tangent.x / magnitude, tangent.y / magnitude};
}

std::optional<Boundary> angle_dimension_overlay(const IdentifiedBoundary& source,
                                                const BoundaryDimension& dimension) {
    const auto first = std::find_if(source.segments.begin(), source.segments.end(),
                                    [&](const auto& segment) {
                                        return segment.segment_id == dimension.segment_id;
                                    });
    const auto second = std::find_if(source.segments.begin(), source.segments.end(),
                                     [&](const auto& segment) {
                                         return segment.segment_id == dimension.secondary_segment_id;
                                     });
    if (first == source.segments.end() || second == source.segments.end()) {
        return std::nullopt;
    }
    const auto first_tangent = dimension_tangent_at_vertex(*first, dimension.vertex_id);
    const auto second_tangent = dimension_tangent_at_vertex(*second, dimension.vertex_id);
    if (!first_tangent || !second_tangent) {
        return std::nullopt;
    }
    Vec2 vertex{};
    bool vertex_found = false;
    const auto find_vertex = [&](const IdentifiedSegment& segment) {
        if (segment.start_vertex_id == dimension.vertex_id) {
            vertex = segment.segment.start;
            vertex_found = true;
        } else if (segment.end_vertex_id == dimension.vertex_id) {
            vertex = segment.segment.end;
            vertex_found = true;
        }
    };
    find_vertex(*first);
    if (!vertex_found) find_vertex(*second);
    if (!vertex_found) return std::nullopt;

    const auto cross = first_tangent->x * second_tangent->y -
                       first_tangent->y * second_tangent->x;
    const auto dot = first_tangent->x * second_tangent->x +
                     first_tangent->y * second_tangent->y;
    const auto sweep = std::atan2(cross, dot);
    if (!std::isfinite(sweep) || std::abs(sweep) <= 1e-7) {
        return std::nullopt;
    }
    const auto requested_radius = std::hypot(dimension.text_position.x - vertex.x,
                                             dimension.text_position.y - vertex.y);
    const auto first_length = segment_length(first->segment);
    const auto second_length = segment_length(second->segment);
    const auto fallback_radius = std::max(0.25, std::min(first_length, second_length) * 0.25);
    const auto radius = std::isfinite(requested_radius) && requested_radius > 1e-7
                            ? requested_radius
                            : fallback_radius;
    if (!(radius > 1e-7) || !std::isfinite(radius)) return std::nullopt;
    const auto first_angle = std::atan2(first_tangent->y, first_tangent->x);
    const Vec2 start{vertex.x + radius * std::cos(first_angle),
                     vertex.y + radius * std::sin(first_angle)};
    const Vec2 end{vertex.x + radius * std::cos(first_angle + sweep),
                   vertex.y + radius * std::sin(first_angle + sweep)};
    return Boundary{Segment{vertex, start, 0.0}, Segment{start, end, sweep},
                    Segment{end, vertex, 0.0}};
}

Vec2 assembly_placement_point(Vec2 point, const AssemblyPlacement& placement) {
    const auto scaled_x = point.x * placement.scale;
    const auto scaled_y = point.y * placement.scale;
    const auto cosine = std::cos(placement.rotation_radians);
    const auto sine = std::sin(placement.rotation_radians);
    return {cosine * scaled_x - sine * scaled_y + placement.translation_m.x,
            sine * scaled_x + cosine * scaled_y + placement.translation_m.y};
}

Boundary assembly_placement_boundary(const Boundary& source,
                                     const AssemblyPlacement& placement) {
    Boundary result;
    result.reserve(source.size());
    for (const auto& segment : source) {
        result.push_back({assembly_placement_point(segment.start, placement),
                          assembly_placement_point(segment.end, placement),
                          segment.sweep_radians});
    }
    return result;
}

Boundary wall_segments_without_openings(const Segment& baseline,
                                         const std::vector<HostedOpening>& openings) {
    if (openings.empty()) {
        return {baseline};
    }
    const auto length = segment_length(baseline);
    if (!(length > 1e-7) || !std::isfinite(length)) {
        return {baseline};
    }
    std::vector<std::pair<double, double>> cuts;
    cuts.reserve(openings.size());
    for (const auto& opening : openings) {
        if (!std::isfinite(opening.offset) || !std::isfinite(opening.width) ||
            opening.width <= 1e-7) {
            continue;
        }
        const auto from = std::clamp(opening.offset / length, 0.0, 1.0);
        const auto to = std::clamp((opening.offset + opening.width) / length, 0.0, 1.0);
        if (to > from + 1e-8) {
            cuts.emplace_back(from, to);
        }
    }
    if (cuts.empty()) {
        return {baseline};
    }
    std::sort(cuts.begin(), cuts.end());
    std::vector<std::pair<double, double>> merged;
    for (const auto cut : cuts) {
        if (merged.empty() || cut.first > merged.back().second + 1e-8) {
            merged.push_back(cut);
        } else {
            merged.back().second = std::max(merged.back().second, cut.second);
        }
    }
    Boundary visible;
    double cursor = 0.0;
    const auto append_interval = [&](double from, double to) {
        if (to <= from + 1e-8) {
            return;
        }
        const auto start = point_at_segment(baseline, from);
        const auto end = point_at_segment(baseline, to);
        if (!start.has_value() || !end.has_value()) {
            return;
        }
        visible.push_back(Segment{*start, *end,
                                  baseline.sweep_radians * (to - from)});
    };
    for (const auto [from, to] : merged) {
        append_interval(cursor, from);
        cursor = std::max(cursor, to);
    }
    append_interval(cursor, 1.0);
    return visible.empty() ? Boundary{baseline} : visible;
}

std::string trim_ascii(std::string_view value) {
    std::size_t first = 0;
    while (first < value.size() && std::isspace(static_cast<unsigned char>(value[first]))) {
        ++first;
    }
    std::size_t last = value.size();
    while (last > first && std::isspace(static_cast<unsigned char>(value[last - 1]))) {
        --last;
    }
    return std::string(value.substr(first, last - first));
}

std::int64_t parse_factor_integer(std::string_view token) {
    const auto trimmed = trim_ascii(token);
    if (trimmed.empty()) {
        throw std::invalid_argument("factor numerator and denominator must be integers");
    }
    std::int64_t result = 0;
    const auto* first = trimmed.data();
    const auto* last = first + trimmed.size();
    const auto parsed = std::from_chars(first, last, result);
    if (parsed.ec != std::errc{} || parsed.ptr != last) {
        throw std::invalid_argument("factor numerator and denominator must be integers");
    }
    return result;
}

std::uint64_t parse_factor_digits(std::string_view digits) {
    if (digits.empty()) {
        throw std::invalid_argument("factor must contain digits");
    }
    std::uint64_t result = 0;
    constexpr auto maximum = std::numeric_limits<std::uint64_t>::max();
    for (const auto character : digits) {
        if (character < '0' || character > '9') {
            throw std::invalid_argument("factor must be a decimal or rational number");
        }
        const auto digit = static_cast<std::uint64_t>(character - '0');
        if (result > (maximum - digit) / 10) {
            throw std::invalid_argument("factor exceeds the supported numeric range");
        }
        result = result * 10 + digit;
    }
    return result;
}

ExactRational parse_factor_expression(const QString& expression) {
    const auto text = trim_ascii(expression.trimmed().toStdString());
    if (text.empty()) {
        throw std::invalid_argument("factor cannot be empty");
    }
    const auto slash = text.find('/');
    if (slash != std::string::npos) {
        if (text.find('/', slash + 1) != std::string::npos) {
            throw std::invalid_argument("factor can contain only one rational slash");
        }
        auto numerator = parse_factor_integer(text.substr(0, slash));
        const auto denominator = parse_factor_integer(text.substr(slash + 1));
        if (numerator < 0 || denominator <= 0) {
            throw std::invalid_argument("factor must be nonnegative with a positive denominator");
        }
        const auto divisor = std::gcd(numerator, denominator);
        return {numerator / divisor, denominator / divisor};
    }

    bool negative = false;
    std::size_t offset = 0;
    if (text.front() == '+' || text.front() == '-') {
        negative = text.front() == '-';
        offset = 1;
    }
    if (negative || offset == text.size()) {
        throw std::invalid_argument("factor must be nonnegative");
    }
    const auto unsigned_text = std::string_view(text).substr(offset);
    const auto dot = unsigned_text.find('.');
    if (dot != std::string_view::npos &&
        unsigned_text.find('.', dot + 1) != std::string_view::npos) {
        throw std::invalid_argument("factor must be a decimal or rational number");
    }
    const auto whole_digits = dot == std::string_view::npos
                                  ? unsigned_text
                                  : unsigned_text.substr(0, dot);
    const auto fractional_digits = dot == std::string_view::npos
                                       ? std::string_view{}
                                       : unsigned_text.substr(dot + 1);
    if (whole_digits.empty() && fractional_digits.empty()) {
        throw std::invalid_argument("factor must contain digits");
    }
    const auto whole = whole_digits.empty() ? 0 : parse_factor_digits(whole_digits);
    const auto fractional = fractional_digits.empty() ? 0 : parse_factor_digits(fractional_digits);
    std::uint64_t denominator = 1;
    for (std::size_t index = 0; index < fractional_digits.size(); ++index) {
        if (denominator > std::numeric_limits<std::uint64_t>::max() / 10) {
            throw std::invalid_argument("factor exceeds the supported numeric range");
        }
        denominator *= 10;
    }
    if (whole > (std::numeric_limits<std::uint64_t>::max() - fractional) / denominator) {
        throw std::invalid_argument("factor exceeds the supported numeric range");
    }
    const auto numerator = whole * denominator + fractional;
    if (numerator > static_cast<std::uint64_t>(std::numeric_limits<std::int64_t>::max()) ||
        denominator > static_cast<std::uint64_t>(std::numeric_limits<std::int64_t>::max())) {
        throw std::invalid_argument("factor exceeds the supported numeric range");
    }
    const auto signed_numerator = static_cast<std::int64_t>(numerator);
    const auto signed_denominator = static_cast<std::int64_t>(denominator);
    const auto divisor = std::gcd(signed_numerator, signed_denominator);
    return {signed_numerator / divisor, signed_denominator / divisor};
}

struct StoredFactor {
    ExactRational rational{1, 1};
    QString expression{QStringLiteral("1")};
};

StoredFactor read_stored_factor(const json& properties) {
    if (properties.contains("factor_numerator") || properties.contains("factor_denominator")) {
        if (!properties.contains("factor_numerator") || !properties.contains("factor_denominator") ||
            !properties.at("factor_numerator").is_number_integer() ||
            !properties.at("factor_denominator").is_number_integer()) {
            throw std::invalid_argument("factor numerator and denominator must be integers");
        }
        const auto numerator = properties.at("factor_numerator").get<std::int64_t>();
        const auto denominator = properties.at("factor_denominator").get<std::int64_t>();
        if (numerator < 0 || denominator <= 0) {
            throw std::invalid_argument("factor must be nonnegative with a positive denominator");
        }
        const auto divisor = std::gcd(numerator, denominator);
        const auto expression = read_string(properties, "factor_expression");
        return {{numerator / divisor, denominator / divisor},
                expression.has_value() ? QString::fromStdString(*expression)
                                       : QStringLiteral("%1/%2").arg(numerator).arg(denominator)};
    }
    if (const auto factor = read_finite_number(properties, "factor")) {
        if (*factor < 0.0) {
            throw std::invalid_argument("factor must be nonnegative");
        }
        std::ostringstream text;
        text.imbue(std::locale::classic());
        text << std::setprecision(std::numeric_limits<double>::max_digits10) << *factor;
        return {parse_factor_expression(QString::fromStdString(text.str())),
                QString::fromStdString(text.str())};
    }
    return {};
}

json stored_factor_json(const StoredFactor& factor) {
    const auto value = static_cast<double>(factor.rational.numerator) /
                       static_cast<double>(factor.rational.denominator);
    return json{{"factor", value},
                {"factor_expression", factor.expression.trimmed().toStdString()},
                {"factor_numerator", factor.rational.numerator},
                {"factor_denominator", factor.rational.denominator}};
}

