    void exportImageFromDialog() {
        const auto selected = QFileDialog::getSaveFileName(
            owner, QStringLiteral("Export draft image"), {}, QStringLiteral("PNG image (*.png)"));
        if (!selected.isEmpty()) {
            exportDraftImage(selected);
        }
    }

